"use client";
import Component from "../smoothui/AnimatedProgressBar";
import { useState } from "react";
import { DemoFrame } from "../shared/DemoFrame";
export default function Demo() {
  const [value, setValue] = useState(42);
  return (
    <DemoFrame hint={value === 100 ? "All assets ready" : "Sample progress"}>
      <div className="w-full max-w-sm">
        <Component value={value} label={`Uploading assets · ${value}%`} color="#0088ff" />
        <div className="mt-7 flex gap-3">
          <button
            className="demo-action"
            onClick={() => setValue(Math.min(value + 19, 100))}
            disabled={value === 100}
          >
            Advance
          </button>
          <button className="demo-action" onClick={() => setValue(0)}>
            Reset
          </button>
        </div>
      </div>
    </DemoFrame>
  );
}

/** Example and adapters: Copyright (c) 2026 NikroZorkin. MIT; licenses/elements.txt. */
import type { ReactNode } from "react";

/** Layout for this example only. The component itself has no catalog dependency. */
export function DemoFrame({
  children,
  className = "",
  hint,
}: {
  children: ReactNode;
  className?: string;
  hint?: string;
}) {
  return (
    <div
      className={`relative flex min-h-[420px] w-full flex-col items-center justify-center gap-7 overflow-hidden p-8 ${className}`}
    >
      {children}
      {hint && (
        <p className="text-center text-xs text-muted-foreground" role="status">
          {hint}
        </p>
      )}
    </div>
  );
}

